class PrimaryKeyJoin(LazyFrameResolver):
    def __init__(
        self,
        left: pl.LazyFrame,
        right: pl.LazyFrame,
        right_schema: SchemaDict,
        on: list[str],
    ):
        self.left = left
        self.right = right
        self.joined = left.join(right, on=on)
        self.on = on

    def schema(self) -> pl.Schema:
        return self.joined.collect_schema()

    def resolve_lazyframe(
        self,
        *,
        projection: list[str] | None,
        limit: int | None,
        filters: list[FilterExpr],
        filter_columns: list[str],
        filter_drop_columns_idx: int | None,
        existing_resolved_version_key: str | None,
    ) -> pl.LazyFrame | tuple[pl.LazyFrame | None, ResolvedLazyFrameProps]:
        if projection is not None:
            # Only collect on IR resolving
            right_schema = self.right.collect_schema()
            if all(
                name not in right_schema or name in self.on for name in projection
            ):
                return self.left

        return self.joined

```

